  {path="/Game/Configs/Technology/DT_TechnologyConfig.DT_TechnologyConfig", struct="FTechnologyConfigStruct", name="DT_TechnologyConfig", rows={
    ["101"]={{{"TechDesc"},"Lets you farm: plant wheat, cotton and hay on farmland. Unlocks: Wheat (planting), Cotton (planting), Hay (planting) and Letters."},{{"FormatItemTechDesc","TextMain"},"Lets you farm: plant wheat, cotton and hay on farmland. Unlocks: Wheat (planting), Cotton (planting), Hay (planting) and Letters."}},
    ["102"]={{{"TechDesc"},"Lets you build the Handcraft Bench and make wooden tools, simple rations and basic wound medicine. Unlocks: Handcraft Bench, Wooden Tools, Dry Rations, Street Lamp, Curious Rock, Kudzu Bandage and Golden Wound Powder."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Handcraft Bench and make wooden tools, simple rations and basic wound medicine. Unlocks: Handcraft Bench, Wooden Tools, Dry Rations, Street Lamp, Curious Rock, Kudzu Bandage and Golden Wound Powder."}},
    ["201"]={{{"TechDesc"},"Lets you build a Millstone to grind grain into flour, and bake flatbread and porridge. Unlocks: Millstone, Flour, Haystack, Flatbread, Porridge and Large Wine Jar."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Millstone to grind grain into flour, and bake flatbread and porridge. Unlocks: Millstone, Flour, Haystack, Flatbread, Porridge and Large Wine Jar."}},
    ["202"]={{{"TechDesc"},"Lets you build a Drying Rack to make jerky and dried fruit, which keep longer. Unlocks: Drying Rack, Jerky and Dried Fruit."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Drying Rack to make jerky and dried fruit, which keep longer. Unlocks: Drying Rack, Jerky and Dried Fruit."}},
    ["203"]={{{"TechDesc"},"Lets you build your first proper houses: foundations first, then walls, roofs, doors and windows, plus wooden pillars and railings. Unlocks: Basic Building Foundation, Basic Walls & Roofs, Shelf, Pine (planting), Wall Lamp, Plain Wood and Bamboo Pillars and Wooden Railings."},{{"FormatItemTechDesc","TextMain"},"Lets you build your first proper houses: foundations first, then walls, roofs, doors and windows, plus wooden pillars and railings. Unlocks: Basic Building Foundation, Basic Walls & Roofs, Shelf, Pine (planting), Wall Lamp, Plain Wood and Bamboo Pillars and Wooden Railings."}},
    ["204"]={{{"TechDesc"},"Lets you build outdoor stone tables and stools for disciples to eat at, and a Practice Stage for melee training. Unlocks: Outdoor Stone Stool, Outdoor Stone Table and Practice Stage."},{{"FormatItemTechDesc","TextMain"},"Lets you build outdoor stone tables and stools for disciples to eat at, and a Practice Stage for melee training. Unlocks: Outdoor Stone Stool, Outdoor Stone Table and Practice Stage."}},
    ["205"]={{{"TechDesc"},"Lets you build a simple wooden fence to protect the sect, and bamboo fences with gates. Unlike house walls, fences take up a whole tile. Unlocks: Fence, plus Bamboo Fences and Gates."},{{"FormatItemTechDesc","TextMain"},"Lets you build a simple wooden fence to protect the sect, and bamboo fences with gates. Unlike house walls, fences take up a whole tile. Unlocks: Fence, plus Bamboo Fences and Gates."}},
    ["704"]={{{"TechDesc"},"Lets you build wooden barricades to keep enemies out, and a Writing Desk for reading. Unlocks: Wooden Barricade, Writing Desk and Ornament: Leisure Books."},{{"FormatItemTechDesc","TextMain"},"Lets you build wooden barricades to keep enemies out, and a Writing Desk for reading. Unlocks: Wooden Barricade, Writing Desk and Ornament: Leisure Books."}},
    ["705"]={{{"TechDesc"},"Lets you build courtyard walls and gates around the sect, plus decorative courtyard gates. Unlocks: Courtyard Wall, Courtyard Gate and Decorative Courtyard Gates."},{{"FormatItemTechDesc","TextMain"},"Lets you build courtyard walls and gates around the sect, plus decorative courtyard gates. Unlocks: Courtyard Wall, Courtyard Gate and Decorative Courtyard Gates."}},
    ["706"]={{{"TechDesc"},"Lets you build Jiangnan-style house parts, preset Jiangnan houses and Jiangnan window walls. Unlocks: Jiangnan Structures, Jiangnan Houses, Lotus Shadow Screen Wall and Jiangnan Window Walls."},{{"FormatItemTechDesc","TextMain"},"Lets you build Jiangnan-style house parts, preset Jiangnan houses and Jiangnan window walls. Unlocks: Jiangnan Structures, Jiangnan Houses, Lotus Shadow Screen Wall and Jiangnan Window Walls."}},
    ["301"]={{{"TechDesc"},"Lets you build a Stone Pot Stove for home-style cooking, a Water Vat that speeds up nearby cooking, and new stews, soups and animal feed. Unlocks: Stone Pot Stove, Water Vat, Fruit Soup, Advanced Meat Feed, Advanced Vegetarian Feed, Big Pot Stew and Quiet Six Treasures Stew."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Stone Pot Stove for home-style cooking, a Water Vat that speeds up nearby cooking, and new stews, soups and animal feed. Unlocks: Stone Pot Stove, Water Vat, Fruit Soup, Advanced Meat Feed, Advanced Vegetarian Feed, Big Pot Stew and Quiet Six Treasures Stew."}},
    ["302"]={{{"TechDesc"},"Lets you build a Well, a Firewood Pile, and the areas where goods are bought and sold at the post station. Unlocks: Well, Firewood Pile, Poplar (planting), Purchase Area and Selling Area."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Well, a Firewood Pile, and the areas where goods are bought and sold at the post station. Unlocks: Well, Firewood Pile, Poplar (planting), Purchase Area and Selling Area."}},
    ["303"]={{{"TechDesc"},"Lets you furnish bedrooms with beds, lamps and wardrobes, and build a Recovery Bed for the injured. Unlocks: Wooden Bed, Oil Lamp, Wardrobe, Palace Lantern, Ornament: Easel, Kudzu Vine (planting), Recovery Bed and Single Bed."},{{"FormatItemTechDesc","TextMain"},"Lets you furnish bedrooms with beds, lamps and wardrobes, and build a Recovery Bed for the injured. Unlocks: Wooden Bed, Oil Lamp, Wardrobe, Palace Lantern, Ornament: Easel, Kudzu Vine (planting), Recovery Bed and Single Bed."}},
    ["304"]={{{"TechDesc"},"Lets you build storage chests, small screens and simple room decorations. Unlocks: Storage Chest, Small Screen, Hanging Scroll: Swift Hooves and Indoor Rockery."},{{"FormatItemTechDesc","TextMain"},"Lets you build storage chests, small screens and simple room decorations. Unlocks: Storage Chest, Small Screen, Hanging Scroll: Swift Hooves and Indoor Rockery."}},
    ["305"]={{{"TechDesc"},"Lets you build a Sandbag for fist training, a Sword Whetstone and a Meditation Cushion, plus some garden plants. Unlocks: Sandbag, Birch (planting), Hibiscus Flowerbed, Ornamental Willow, Sword Whetstone and Meditation Cushion."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Sandbag for fist training, a Sword Whetstone and a Meditation Cushion, plus some garden plants. Unlocks: Sandbag, Birch (planting), Hibiscus Flowerbed, Ornamental Willow, Sword Whetstone and Meditation Cushion."}},
    ["401"]={{{"TechDesc"},"Lets you set up a dining hall with tables, stools, tableware and an Ice Chest that keeps food fresh. Unlocks: Menu Board, Wooden Table, Stool, Tableware and Ice Chest."},{{"FormatItemTechDesc","TextMain"},"Lets you set up a dining hall with tables, stools, tableware and an Ice Chest that keeps food fresh. Unlocks: Menu Board, Wooden Table, Stool, Tableware and Ice Chest."}},
    ["402"]={{{"TechDesc"},"Lets you build a swing, a double bed, an armchair and a large bookshelf for disciples to relax. Unlocks: Swing, Double Bed, Horseshoe Armchair and Large Bookshelf."},{{"FormatItemTechDesc","TextMain"},"Lets you build a swing, a double bed, an armchair and a large bookshelf for disciples to relax. Unlocks: Swing, Double Bed, Horseshoe Armchair and Large Bookshelf."}},
    ["403"]={{{"TechDesc"},"Lets you upgrade the dining hall with luxury tables and chairs, a large screen and an ice sculpture. Unlocks: Luxury Table, Luxury Chair, Large Folding Screen and Ice Sculpture."},{{"FormatItemTechDesc","TextMain"},"Lets you upgrade the dining hall with luxury tables and chairs, a large screen and an ice sculpture. Unlocks: Luxury Table, Luxury Chair, Large Folding Screen and Ice Sculpture."}},
    ["404"]={{{"TechDesc"},"Lets you build facilities that restore disciples' Insight, which training uses up. Unlocks: Guqin Stand, Ancient Sword Statue and Lotus Meditation Pond."},{{"FormatItemTechDesc","TextMain"},"Lets you build facilities that restore disciples' Insight, which training uses up. Unlocks: Guqin Stand, Ancient Sword Statue and Lotus Meditation Pond."}},
    ["405"]={{{"TechDesc"},"Lets you build decorative ponds. Water decorations are placed on ponds. Unlocks: Pond and Water Rock - I."},{{"FormatItemTechDesc","TextMain"},"Lets you build decorative ponds. Water decorations are placed on ponds. Unlocks: Pond and Water Rock - I."}},
    ["406"]={{{"TechDesc"},"Lets you place decorative rocks and stone pagodas in ponds. Unlocks: Taihu Stone and Three Pools Mirroring the Moon."},{{"FormatItemTechDesc","TextMain"},"Lets you place decorative rocks and stone pagodas in ponds. Unlocks: Taihu Stone and Three Pools Mirroring the Moon."}},
    ["407"]={{{"TechDesc"},"Lets you place water plants in ponds to decorate them. Unlocks: Duckweed, Lotus Leaf, Lily Pad, Water Lily and Giant Water Lily."},{{"FormatItemTechDesc","TextMain"},"Lets you place water plants in ponds to decorate them. Unlocks: Duckweed, Lotus Leaf, Lily Pad, Water Lily and Giant Water Lily."}},
    ["408"]={{{"TechDesc"},"Lets you place decorative lanterns and lotus ornaments in ponds. Unlocks: Lotus Lantern and Glazed Lotus."},{{"FormatItemTechDesc","TextMain"},"Lets you place decorative lanterns and lotus ornaments in ponds. Unlocks: Lotus Lantern and Glazed Lotus."}},
    ["409"]={{{"TechDesc"},"Lets you build covered and arched bridges over water, for decoration or for disciples to cross. Unlocks: Covered Water Bridge and Arch Bridge."},{{"FormatItemTechDesc","TextMain"},"Lets you build covered and arched bridges over water, for decoration or for disciples to cross. Unlocks: Covered Water Bridge and Arch Bridge."}},
    ["501"]={{{"TechDesc"},"Lets you grow tea bushes and brew tea and black tea. Unlocks: Tea Bush (planting), Tea, Black Tea and Fermented Tea Leaves."},{{"FormatItemTechDesc","TextMain"},"Lets you grow tea bushes and brew tea and black tea. Unlocks: Tea Bush (planting), Tea, Black Tea and Fermented Tea Leaves."}},
    ["502"]={{{"TechDesc"},"Lets you build more room decorations, a big drum, an Iron Tool Cage that raises work efficiency, and indoor partitions. Unlocks: Bamboo Shadow in the Wind, Dark Leaf Pattern, Censer: Crane Aloft, Censer: Soaring Crane, Iron Tool Cage, Big Drum and Indoor Partitions."},{{"FormatItemTechDesc","TextMain"},"Lets you build more room decorations, a big drum, an Iron Tool Cage that raises work efficiency, and indoor partitions. Unlocks: Bamboo Shadow in the Wind, Dark Leaf Pattern, Censer: Crane Aloft, Censer: Soaring Crane, Iron Tool Cage, Big Drum and Indoor Partitions."}},
    ["503"]={{{"TechDesc"},"Lets you build a Steamer and cook more home-style dishes and fruit feed. Unlocks: Steamer, Jujube Paste Cake, Home-Style Four Joys Stew, Fruit Feed and Lotus Seed Cake."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Steamer and cook more home-style dishes and fruit feed. Unlocks: Steamer, Jujube Paste Cake, Home-Style Four Joys Stew, Fruit Feed and Lotus Seed Cake."}},
    ["601"]={{{"TechDesc"},"Lets you farm paddy fields to grow rice, and plant lotus and corn. Unlocks: Lotus Seed (planting), Rice (planting) and Corn (planting)."},{{"FormatItemTechDesc","TextMain"},"Lets you farm paddy fields to grow rice, and plant lotus and corn. Unlocks: Lotus Seed (planting), Rice (planting) and Corn (planting)."}},
    ["602"]={{{"TechDesc"},"Lets you build the Sect Gate with its archway, guiding stones and welcome pavilion, the Hundred Treasures Tower shop, and a plaque with your sect's name. Unlocks: Sect Gate, Sect Gate Archway, Guiding Stone, Welcome Pavilion, Hundred Treasures Tower and Plain Sect Plaque."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Sect Gate with its archway, guiding stones and welcome pavilion, the Hundred Treasures Tower shop, and a plaque with your sect's name. Unlocks: Sect Gate, Sect Gate Archway, Guiding Stone, Welcome Pavilion, Hundred Treasures Tower and Plain Sect Plaque."}},
    ["603"]={{{"TechDesc"},"Lets you plant decorative flowerbeds and ornamental trees. Unlocks: Peony Flowerbed and Ornamental Pagoda Tree."},{{"FormatItemTechDesc","TextMain"},"Lets you plant decorative flowerbeds and ornamental trees. Unlocks: Peony Flowerbed and Ornamental Pagoda Tree."}},
    ["701"]={{{"TechDesc"},"Lets you build the Star Energy Stove and cook fine dishes. Unlocks: Star Energy Stove, Longan and Lotus Seed Soup, Pine Nut and Lily Pastry, Charcoal-Grilled Chops, Sliced Raw Fish and Spring Dew Glowshine Cake."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Star Energy Stove and cook fine dishes. Unlocks: Star Energy Stove, Longan and Lotus Seed Soup, Pine Nut and Lily Pastry, Charcoal-Grilled Chops, Sliced Raw Fish and Spring Dew Glowshine Cake."}},
    ["702"]={{{"TechDesc"},"Lets you build a Pigeon Coop to hear news from the jianghu, and a Stable to unlock riding. Unlocks: Pigeon Coop and Stable."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Pigeon Coop to hear news from the jianghu, and a Stable to unlock riding. Unlocks: Pigeon Coop and Stable."}},
    ["703"]={{{"TechDesc"},"Lets you build a luxury bed, a long curio bookshelf, more room decorations and carved arches. Unlocks: Cloud-Shadow Moon Lantern, Long Curio Bookshelf, Luxury Bed, Wall Hanging: Paper Kite, Carved Arches and In-Wall Arches."},{{"FormatItemTechDesc","TextMain"},"Lets you build a luxury bed, a long curio bookshelf, more room decorations and carved arches. Unlocks: Cloud-Shadow Moon Lantern, Long Curio Bookshelf, Luxury Bed, Wall Hanging: Paper Kite, Carved Arches and In-Wall Arches."}},
    ["707"]={{{"TechDesc"},"Lets you build the Shuttle Platform for fast but costly travel across the world. Unlocks: Shuttle Platform."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Shuttle Platform for fast but costly travel across the world. Unlocks: Shuttle Platform."}},
    ["801"]={{{"TechDesc"},"Lets you build a Brewing Barrel to make rice wine and fruit wine, and a Wine Cabinet to store them. Unlocks: Brewing Barrel, Rice Wine, Fruit Wine and Wine Cabinet."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Brewing Barrel to make rice wine and fruit wine, and a Wine Cabinet to store them. Unlocks: Brewing Barrel, Rice Wine, Fruit Wine and Wine Cabinet."}},
    ["802"]={{{"TechDesc"},"Lets you build sturdier brick and stone houses with twice the durability, plus bluestone railings and stone pillars. Unlocks: Brick and Stone Buildings, Bluestone Brick House, Bluestone Brick Longhouse, Bluestone Railing and Stone Pillars."},{{"FormatItemTechDesc","TextMain"},"Lets you build sturdier brick and stone houses with twice the durability, plus bluestone railings and stone pillars. Unlocks: Brick and Stone Buildings, Bluestone Brick House, Bluestone Brick Longhouse, Bluestone Railing and Stone Pillars."}},
    ["803"]={{{"TechDesc"},"Lets you build a Reading Desk so disciples read faster, plus study decorations. Unlocks: Reading Desk, Ornament: Brush Rack and Candlestick."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Reading Desk so disciples read faster, plus study decorations. Unlocks: Reading Desk, Ornament: Brush Rack and Candlestick."}},
    ["804"]={{{"TechDesc"},"Lets you build a notice board, a drum and street lamps, and opens the Overworld. Unlocks: Notice Board, Mountain-Shaking Drum, Double Lantern Street Lamp, Octagonal Street Lamp, Brazier and Overworld."},{{"FormatItemTechDesc","TextMain"},"Lets you build a notice board, a drum and street lamps, and opens the Overworld. Unlocks: Notice Board, Mountain-Shaking Drum, Double Lantern Street Lamp, Octagonal Street Lamp, Brazier and Overworld."}},
    ["901"]={{{"TechDesc"},"Lets you cook advanced fine dishes. Unlocks: Braised Head Course, Nine Sauces Casserole, Five Vegetables Fragrant Meat, Mountain Spirit Eight Treasures Stew, Softshell Turtle Eight Treasures Soup, Stir-Fried Soy Sauce Dish, Kung Pao Fowl and Tea-Scented Meat."},{{"FormatItemTechDesc","TextMain"},"Lets you cook advanced fine dishes. Unlocks: Braised Head Course, Nine Sauces Casserole, Five Vegetables Fragrant Meat, Mountain Spirit Eight Treasures Stew, Softshell Turtle Eight Treasures Soup, Stir-Fried Soy Sauce Dish, Kung Pao Fowl and Tea-Scented Meat."}},
    ["902"]={{{"TechDesc"},"Lets you build facilities for training internal arts: the Medicinal Bath, Star Stone and Cold Jade Bed. Unlocks: Medicinal Bath, Star Stone, Cold Jade Bed, Ornament: Green-Patterned Bloom and Ornament: Red on Celadon."},{{"FormatItemTechDesc","TextMain"},"Lets you build facilities for training internal arts: the Medicinal Bath, Star Stone and Cold Jade Bed. Unlocks: Medicinal Bath, Star Stone, Cold Jade Bed, Ornament: Green-Patterned Bloom and Ornament: Red on Celadon."}},
    ["903"]={{{"TechDesc"},"Lets you build training equipment for martial arts practice. Unlocks: Wooden Dummy, Stone Weight, Plum Shadow Porcelain, Waterwheel Kick Trainer and Jar Grip Trainer."},{{"FormatItemTechDesc","TextMain"},"Lets you build training equipment for martial arts practice. Unlocks: Wooden Dummy, Stone Weight, Plum Shadow Porcelain, Waterwheel Kick Trainer and Jar Grip Trainer."}},
    ["904"]={{{"TechDesc"},"Lets you build a prison to hold captives, plus an execution platform, a standing cage and a flogging rack. Unlocks: Prison Door, Prison Wall, Execution Platform, Standing Cage and Flogging Rack."},{{"FormatItemTechDesc","TextMain"},"Lets you build a prison to hold captives, plus an execution platform, a standing cage and a flogging rack. Unlocks: Prison Door, Prison Wall, Execution Platform, Standing Cage and Flogging Rack."}},
    ["905"]={{{"TechDesc"},"Lets you build targets for training ranged and hidden weapon moves. Unlocks: Archery Target, Spinning Dart Target, Pitch-Pot and Embroidery Hoop."},{{"FormatItemTechDesc","TextMain"},"Lets you build targets for training ranged and hidden weapon moves. Unlocks: Archery Target, Spinning Dart Target, Pitch-Pot and Embroidery Hoop."}},
    ["906"]={{{"TechDesc"},"Lets you build equipment for training sword, saber and spear moves, and a weapon rack. Unlocks: Sword-Testing Stone, Armored Mannequin, Zhenwu Demon-Subduing Statue, Longquan Sword, Weapon Rack and Sword Dance Screen."},{{"FormatItemTechDesc","TextMain"},"Lets you build equipment for training sword, saber and spear moves, and a weapon rack. Unlocks: Sword-Testing Stone, Armored Mannequin, Zhenwu Demon-Subduing Statue, Longquan Sword, Weapon Rack and Sword Dance Screen."}},
    ["907"]={{{"TechDesc"},"Lets you plant more flowerbeds and ornamental trees, and build a flower gallery. Unlocks: Chinese Rose Flowerbed, Ornamental Pine, Ornament: Gnarled Green Branches, Ornamental Parasol Tree and Flower Gallery."},{{"FormatItemTechDesc","TextMain"},"Lets you plant more flowerbeds and ornamental trees, and build a flower gallery. Unlocks: Chinese Rose Flowerbed, Ornamental Pine, Ornament: Gnarled Green Branches, Ornamental Parasol Tree and Flower Gallery."}},
    ["908"]={{{"TechDesc"},"Lets you build an opera costume rack for decoration. Unlocks: Clothes Rack - Opera Costume."},{{"FormatItemTechDesc","TextMain"},"Lets you build an opera costume rack for decoration. Unlocks: Clothes Rack - Opera Costume."}},
    ["909"]={{{"TechDesc"},"Lets you build houses from glazed bricks and tiles, the finest building tier, plus lacquered pillars. Unlocks: Glazed Buildings, Glazed Structures and Lacquered Pillars."},{{"FormatItemTechDesc","TextMain"},"Lets you build houses from glazed bricks and tiles, the finest building tier, plus lacquered pillars. Unlocks: Glazed Buildings, Glazed Structures and Lacquered Pillars."}},
    ["1101"]={{{"TechDesc"},"Lets you build torches, and a Furnace to fire stone into bricks. Unlocks: Torch, Furnace, Decorative Stove and Bricks and Stone."},{{"FormatItemTechDesc","TextMain"},"Lets you build torches, and a Furnace to fire stone into bricks. Unlocks: Torch, Furnace, Decorative Stove and Bricks and Stone."}},
    ["1102"]={{{"TechDesc"},"Lets you build a Smithing Bench to make weapons. Unlocks: Smithing Bench, Brazier and Curio Shelf."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Smithing Bench to make weapons. Unlocks: Smithing Bench, Brazier and Curio Shelf."}},
    ["1103"]={{{"TechDesc"},"Lets you build a Refining Furnace to make pig iron and fine iron ingots. Unlocks: Refining Furnace, Pig Iron Ingot, Fine Iron Ingot and Moon-Lit Lantern."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Refining Furnace to make pig iron and fine iron ingots. Unlocks: Refining Furnace, Pig Iron Ingot, Fine Iron Ingot and Moon-Lit Lantern."}},
    ["1104"]={{{"TechDesc"},"Lets you refine gold and silver ingots, make better tool kits, and gather minerals faster. Unlocks: Gold Ingot, Silver Ingot, Silver-Inlaid Leather Tool Kit and Quarrying Techniques."},{{"FormatItemTechDesc","TextMain"},"Lets you refine gold and silver ingots, make better tool kits, and gather minerals faster. Unlocks: Gold Ingot, Silver Ingot, Silver-Inlaid Leather Tool Kit and Quarrying Techniques."}},
    ["1105"]={{{"TechDesc"},"Lets you build the facilities that produce Star Energy, and towers that carry it to other buildings. Unlocks: Moonlight Platform, Mohist Thousand-Star Cauldron, Glimmer Platform, Star-Gathering Tube and Star Energy Tower."},{{"FormatItemTechDesc","TextMain"},"Lets you build the facilities that produce Star Energy, and towers that carry it to other buildings. Unlocks: Moonlight Platform, Mohist Thousand-Star Cauldron, Glimmer Platform, Star-Gathering Tube and Star Energy Tower."}},
    ["1106"]={{{"TechDesc"},"Lets you store Star Energy and build things that run on it, such as lamps, a mill, a furnace and a recovery bed. Unlocks: Star Energy Storage Pool, Star Energy Mill, Star Energy Hanging Lamp, Star Energy Street Lamp, Star Energy Palace Lantern, Star Energy Recovery Bed and Star Energy Furnace."},{{"FormatItemTechDesc","TextMain"},"Lets you store Star Energy and build things that run on it, such as lamps, a mill, a furnace and a recovery bed. Unlocks: Star Energy Storage Pool, Star Energy Mill, Star Energy Hanging Lamp, Star Energy Street Lamp, Star Energy Palace Lantern, Star Energy Recovery Bed and Star Energy Furnace."}},
    ["1107"]={{{"TechDesc"},"Lets you build Star Energy heaters, coolers and an ice chest for food. Unlocks: Star Energy Heater, Star Energy Cooler and Star Energy Ice Chest."},{{"FormatItemTechDesc","TextMain"},"Lets you build Star Energy heaters, coolers and an ice chest for food. Unlocks: Star Energy Heater, Star Energy Cooler and Star Energy Ice Chest."}},
    ["1201"]={{{"TechDesc"},"Lets you build a Loom to make cloth, and sew basic cloth clothing. Unlocks: Loom, Basic Cloth, Intermediate Cloth, Advanced Cloth, Beast Accessories, Coarse Cloth Long Robe, Coarse Cloth Trousers and Coarse Hemp Shoes."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Loom to make cloth, and sew basic cloth clothing. Unlocks: Loom, Basic Cloth, Intermediate Cloth, Advanced Cloth, Beast Accessories, Coarse Cloth Long Robe, Coarse Cloth Trousers and Coarse Hemp Shoes."}},
    ["1202"]={{{"TechDesc"},"Lets you build the Mechanical Crossbow, which attacks approaching enemies automatically. Unlocks: Mechanical Crossbow."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Mechanical Crossbow, which attacks approaching enemies automatically. Unlocks: Mechanical Crossbow."}},
    ["1203"]={{{"TechDesc"},"Lets you make intermediate weapons, build a Strategy Sand Table that makes advanced research materials, and refit puppets. Unlocks: Strategy Sand Table, Parting Sorrow Sword, Luchen Spear, Sky-Breaker Bow, Bedrock Gauntlets and Puppet Refit."},{{"FormatItemTechDesc","TextMain"},"Lets you make intermediate weapons, build a Strategy Sand Table that makes advanced research materials, and refit puppets. Unlocks: Strategy Sand Table, Parting Sorrow Sword, Luchen Spear, Sky-Breaker Bow, Bedrock Gauntlets and Puppet Refit."}},
    ["1204"]={{{"TechDesc"},"Lets you build mechanical men to work for the sect, with a bench to make them and stations to recharge them. Unlocks: Mechanical Men, Mechanism Recharging Station, Mechanism Bench, Puppet Refit Platform, Plain Porcelain Bearing, Mechanism: Ink Feather and Ink Crystal Pillar."},{{"FormatItemTechDesc","TextMain"},"Lets you build mechanical men to work for the sect, with a bench to make them and stations to recharge them. Unlocks: Mechanical Men, Mechanism Recharging Station, Mechanism Bench, Puppet Refit Platform, Plain Porcelain Bearing, Mechanism: Ink Feather and Ink Crystal Pillar."}},
    ["1205"]={{{"TechDesc"},"Lets you build the Star Energy Smithing Bench to make high-tier weapons, and new puppets. Unlocks: Star Energy Smithing Bench, Gold-Inlaid Leather Tool Kit, Clear River Sword, Reed Leaf Spear, Green Frost Bow, Tiger Bone Gauntlets, Puppet: Mountain Warden and Puppet: Raging Beast."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Star Energy Smithing Bench to make high-tier weapons, and new puppets. Unlocks: Star Energy Smithing Bench, Gold-Inlaid Leather Tool Kit, Clear River Sword, Reed Leaf Spear, Green Frost Bow, Tiger Bone Gauntlets, Puppet: Mountain Warden and Puppet: Raging Beast."}},
    ["1206"]={{{"TechDesc"},"Lets you build the Zhuge Blade Crossbow and ranged puppets. Unlocks: Zhuge Blade Crossbow, Puppet: Archer and Puppet: Hanging Doll."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Zhuge Blade Crossbow and ranged puppets. Unlocks: Zhuge Blade Crossbow, Puppet: Archer and Puppet: Hanging Doll."}},
    ["1209"]={{{"TechDesc"},"Upgrades your mechanisms and unlocks new puppets. Unlocks: Advanced Mechanisms, Puppet: Hermit and Puppet: Wolf King."},{{"FormatItemTechDesc","TextMain"},"Upgrades your mechanisms and unlocks new puppets. Unlocks: Advanced Mechanisms, Puppet: Hermit and Puppet: Wolf King."}},
    ["1210"]={{{"TechDesc"},"Unlocks advanced puppet modifications. Unlocks: Advanced Puppet Modification."},{{"FormatItemTechDesc","TextMain"},"Unlocks advanced puppet modifications. Unlocks: Advanced Puppet Modification."}},
    ["1301"]={{{"TechDesc"},"Lets you tame animals, and build beds, feeding troughs and feed for them. Unlocks: Taming Animal, Animal Hay Bed, Wooden Animal Feeding Trough, Herbivore Animal Feed and Carnivore Animal Feed."},{{"FormatItemTechDesc","TextMain"},"Lets you tame animals, and build beds, feeding troughs and feed for them. Unlocks: Taming Animal, Animal Hay Bed, Wooden Animal Feeding Trough, Herbivore Animal Feed and Carnivore Animal Feed."}},
    ["1302"]={{{"TechDesc"},"Lets you build the Craftwork Bench to make simple accessories and Mechanism Cores. Unlocks: Mechanism Core, Craftwork Bench, Accessory: Rattle Drum, Accessory: Bamboo Staff, Accessory: Bamboo Slips and Accessory: Bamboo Frame Pack."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Craftwork Bench to make simple accessories and Mechanism Cores. Unlocks: Mechanism Core, Craftwork Bench, Accessory: Rattle Drum, Accessory: Bamboo Staff, Accessory: Bamboo Slips and Accessory: Bamboo Frame Pack."}},
    ["1303"]={{{"TechDesc"},"Lets you build a Sewing Table and make light leather clothing. Unlocks: Sewing Table, Wardrobe, Light Leather Short Jacket, Light Leather Trousers and Light Leather Boots."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Sewing Table and make light leather clothing. Unlocks: Sewing Table, Wardrobe, Light Leather Short Jacket, Light Leather Trousers and Light Leather Boots."}},
    ["1304"]={{{"TechDesc"},"Lets you build a Medicine Table and Medicine Cabinet and make healing medicine. Unlocks: Medicine Table, Medicine Cabinet, Bone-Mending Sinew-Joining Pill and Breeze Detox Salve."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Medicine Table and Medicine Cabinet and make healing medicine. Unlocks: Medicine Table, Medicine Cabinet, Bone-Mending Sinew-Joining Pill and Breeze Detox Salve."}},
    ["1305"]={{{"TechDesc"},"Lets you make gourd and instrument accessories. Unlocks: Accessory: Black Glazed Gourd, Accessory: Yellow Rock Gourd, Accessory: Golden Sand Gourd, Accessory: Guqin, Accessory: Clear-Toned Pipa and Accessory: Jade-Faced Pipa."},{{"FormatItemTechDesc","TextMain"},"Lets you make gourd and instrument accessories. Unlocks: Accessory: Black Glazed Gourd, Accessory: Yellow Rock Gourd, Accessory: Golden Sand Gourd, Accessory: Guqin, Accessory: Clear-Toned Pipa and Accessory: Jade-Faced Pipa."}},
    ["1306"]={{{"TechDesc"},"Lets you make blue cloth and soft leather clothing. Unlocks: Blue Cloth Short Shirt, Blue Cloth Trousers, Blue Cloth Shoes, Soft Leather Vest, Soft Leather Trousers and Soft Leather Boots."},{{"FormatItemTechDesc","TextMain"},"Lets you make blue cloth and soft leather clothing. Unlocks: Blue Cloth Short Shirt, Blue Cloth Trousers, Blue Cloth Shoes, Soft Leather Vest, Soft Leather Trousers and Soft Leather Boots."}},
    ["1307"]={{{"TechDesc"},"Lets you make mid-tier accessories. Unlocks: Accessory: Plum, Accessory: Orchid, Accessory: Bamboo, Accessory: Chrysanthemum and Accessory: Fishing Rod."},{{"FormatItemTechDesc","TextMain"},"Lets you make mid-tier accessories. Unlocks: Accessory: Plum, Accessory: Orchid, Accessory: Bamboo, Accessory: Chrysanthemum and Accessory: Fishing Rod."}},
    ["1308"]={{{"TechDesc"},"Lets you build a Star Energy Loom and make Cloud-Lit and Flying Sunset clothing. Unlocks: Star Energy Loom, Cloud-Lit Long Robe, Cloud-Lit Trousers, Cloud-Lit Shoes, Flying Sunset Outfit, Flying Sunset Trousers and Flying Sunset Boots."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Star Energy Loom and make Cloud-Lit and Flying Sunset clothing. Unlocks: Star Energy Loom, Cloud-Lit Long Robe, Cloud-Lit Trousers, Cloud-Lit Shoes, Flying Sunset Outfit, Flying Sunset Trousers and Flying Sunset Boots."}},
    ["1309"]={{{"TechDesc"},"Lets you make high-tier accessories. Unlocks: Accessory: Short Firearm, Accessory: Blackcloud Ring, Accessory: Commander's Banner, Accessory: Command Flag and Accessory: Back Banners."},{{"FormatItemTechDesc","TextMain"},"Lets you make high-tier accessories. Unlocks: Accessory: Short Firearm, Accessory: Blackcloud Ring, Accessory: Commander's Banner, Accessory: Command Flag and Accessory: Back Banners."}},
    ["1310"]={{{"TechDesc"},"Lets you make the top tier of clothing. Unlocks: Return-to-Truth Brocade Robe, Return-to-Truth Brocade Trousers, Return-to-Truth Brocade Shoes, Xuanyuan Armor Coat, Xuanyuan Armor Trousers and Xuanyuan War Boots."},{{"FormatItemTechDesc","TextMain"},"Lets you make the top tier of clothing. Unlocks: Return-to-Truth Brocade Robe, Return-to-Truth Brocade Trousers, Return-to-Truth Brocade Shoes, Xuanyuan Armor Coat, Xuanyuan Armor Trousers and Xuanyuan War Boots."}},
    ["11001"]={{{"TechDesc"},"Learned from the Daoist sects. Lets you build the Armillary Sphere, which disciples admire to relax. Unlocks: Armillary Sphere."},{{"FormatItemTechDesc","TextMain"},"Learned from the Daoist sects. Lets you build the Armillary Sphere, which disciples admire to relax. Unlocks: Armillary Sphere."}},
    ["11002"]={{{"TechDesc"},"Lets you build the Martial Assessment Desk to test disciples' aptitude, and the Sword Jade Tablet for training moves. Unlocks: Martial Assessment Desk and Sword Jade Tablet."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Martial Assessment Desk to test disciples' aptitude, and the Sword Jade Tablet for training moves. Unlocks: Martial Assessment Desk and Sword Jade Tablet."}},
    ["11003"]={{{"TechDesc"},"Lets you build the Six-Gate Contemplation Pavilion, which restores Insight and teaches a little fist and sword skill. Unlocks: Six-Gate Contemplation Pavilion."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Six-Gate Contemplation Pavilion, which restores Insight and teaches a little fist and sword skill. Unlocks: Six-Gate Contemplation Pavilion."}},
    ["11004"]={{{"TechDesc"},"Lets you build the Statue of Zhenwu the Great Emperor, which gives every disciple Aptitude +50. Unlocks: Statue of Zhenwu the Great Emperor."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Statue of Zhenwu the Great Emperor, which gives every disciple Aptitude +50. Unlocks: Statue of Zhenwu the Great Emperor."}},
    ["12001"]={{{"TechDesc"},"Lets you build the Puppet Platform, where sentry puppets guard the sect, and the Hermit puppet. Unlocks: Puppet Platform and Puppet: Hermit."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Puppet Platform, where sentry puppets guard the sect, and the Hermit puppet. Unlocks: Puppet Platform and Puppet: Hermit."}},
    ["12002"]={{{"TechDesc"},"Unlocks the Mountain Warden puppet. Unlocks: Puppet: Mountain Warden."},{{"FormatItemTechDesc","TextMain"},"Unlocks the Mountain Warden puppet. Unlocks: Puppet: Mountain Warden."}},
    ["12003"]={{{"TechDesc"},"Unlocks the Spider puppet. Unlocks: Puppet: Spider."},{{"FormatItemTechDesc","TextMain"},"Unlocks the Spider puppet. Unlocks: Puppet: Spider."}},
    ["12004"]={{{"TechDesc"},"Unlocks the Hanging Doll puppet. Unlocks: Puppet: Hanging Doll."},{{"FormatItemTechDesc","TextMain"},"Unlocks the Hanging Doll puppet. Unlocks: Puppet: Hanging Doll."}},
    ["13001"]={{{"TechDesc"},"Learned from the Damo Chan Monastery. Lets you build the Eighteen Bronze Men for training moves. Unlocks: Eighteen Bronze Men."},{{"FormatItemTechDesc","TextMain"},"Learned from the Damo Chan Monastery. Lets you build the Eighteen Bronze Men for training moves. Unlocks: Eighteen Bronze Men."}},
    ["13002"]={{{"TechDesc"},"Lets you build the Eight Treasures Cabinet, which now and then turns up lost items. Unlocks: Eight Treasures Cabinet."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Eight Treasures Cabinet, which now and then turns up lost items. Unlocks: Eight Treasures Cabinet."}},
    ["13003"]={{{"TechDesc"},"Lets you build a Pagoda, which gives every disciple Comprehension +5, Aptitude +20 and Attack +50. Unlocks: Pagoda."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Pagoda, which gives every disciple Comprehension +5, Aptitude +20 and Attack +50. Unlocks: Pagoda."}},
    ["13004"]={{{"TechDesc"},"Lets you build the Golden Buddha Statue, a large wonder disciples admire to relax. Unlocks: Golden Buddha Statue."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Golden Buddha Statue, a large wonder disciples admire to relax. Unlocks: Golden Buddha Statue."}},
    ["14001"]={{{"TechDesc"},"Learned from the Tianxia Society. Lets you build the Group Training Hall, which trains more disciples at once. Unlocks: Group Training Hall."},{{"FormatItemTechDesc","TextMain"},"Learned from the Tianxia Society. Lets you build the Group Training Hall, which trains more disciples at once. Unlocks: Group Training Hall."}},
    ["14002"]={{{"TechDesc"},"Lets you build the Altar of Heaven, which gives every disciple Movement Speed +30, Running Speed +30, carry weight +50 and Attack +50. Unlocks: Altar of Heaven."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Altar of Heaven, which gives every disciple Movement Speed +30, Running Speed +30, carry weight +50 and Attack +50. Unlocks: Altar of Heaven."}},
    ["14003"]={{{"TechDesc"},"Lets you build the Waterside Chess Pavilion, where disciples restore Insight and gain a little internal art EXP. Unlocks: Waterside Chess Pavilion."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Waterside Chess Pavilion, where disciples restore Insight and gain a little internal art EXP. Unlocks: Waterside Chess Pavilion."}},
    ["14004"]={{{"TechDesc"},"Lets you build the Langhuan Jade Statue, which gives every disciple Comprehension +10. Unlocks: Langhuan Jade Statue."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Langhuan Jade Statue, which gives every disciple Comprehension +10. Unlocks: Langhuan Jade Statue."}},
    ["1311"]={{{"TechDesc"},"Unlocks free sect outfits for all disciples. Unlocks: Smart-Faced Clothes and Brown Leather Short Outfit."},{{"FormatItemTechDesc","TextMain"},"Unlocks free sect outfits for all disciples. Unlocks: Smart-Faced Clothes and Brown Leather Short Outfit."}},
    ["1312"]={{{"TechDesc"},"Unlocks the next set of free sect outfits for all disciples. Unlocks: Dark Clothes and Plain Fabric Clothes."},{{"FormatItemTechDesc","TextMain"},"Unlocks the next set of free sect outfits for all disciples. Unlocks: Dark Clothes and Plain Fabric Clothes."}},
    ["1313"]={{{"TechDesc"},"Unlocks the top set of free sect outfits for all disciples. Unlocks: Refined Clothes and Fine-Cut Clothes."},{{"FormatItemTechDesc","TextMain"},"Unlocks the top set of free sect outfits for all disciples. Unlocks: Refined Clothes and Fine-Cut Clothes."}},
    ["1314"]={{{"TechDesc"},"Unlocks the Sect Master's two sets of attire. Unlocks: Sect Master Attire (Black Dragon Blazing Armor) and Sect Master Attire (Rosy Cloud Bodice)."},{{"FormatItemTechDesc","TextMain"},"Unlocks the Sect Master's two sets of attire. Unlocks: Sect Master Attire (Black Dragon Blazing Armor) and Sect Master Attire (Rosy Cloud Bodice)."}},
    ["1108"]={{{"TechDesc"},"Lets you build mines that keep producing ore, powered by Star Energy. Unlocks: Black Iron Mine, Silver Mine, Gold Mine and Xirang."},{{"FormatItemTechDesc","TextMain"},"Lets you build mines that keep producing ore, powered by Star Energy. Unlocks: Black Iron Mine, Silver Mine, Gold Mine and Xirang."}},
    ["1109"]={{{"TechDesc"},"Lets you build a Star Crystal Mine. Unlocks: Star Crystal Mine."},{{"FormatItemTechDesc","TextMain"},"Lets you build a Star Crystal Mine. Unlocks: Star Crystal Mine."}},
    ["10001"]={{{"TechDesc"},"Lets you build the Martial Arena, where disciples spar to test their skill. Unlocks: Martial Arena."},{{"FormatItemTechDesc","TextMain"},"Lets you build the Martial Arena, where disciples spar to test their skill. Unlocks: Martial Arena."}},
    ["10002"]={{{"TechDesc"},"Lets you build furniture and lamps from the Fengsha Gang's homeland. Unlocks: Fengsha Gang Furnishings and Fengsha Gang Lamps."},{{"FormatItemTechDesc","TextMain"},"Lets you build furniture and lamps from the Fengsha Gang's homeland. Unlocks: Fengsha Gang Furnishings and Fengsha Gang Lamps."}},
    ["Tech_GraveRites"]={{{"TechDesc"},"Lets you bury the dead and build an ancestral hall to honor them. Unlocks: Burying, Ancestral Hall Parts and Ancestral Hall Decor."},{{"FormatItemTechDesc","TextMain"},"Lets you bury the dead and build an ancestral hall to honor them. Unlocks: Burying, Ancestral Hall Parts and Ancestral Hall Decor."}},
  }},
  {path="/Game/Configs/Character/DT_CommonBuff.DT_CommonBuff", struct="FCommonBuff", name="DT_CommonBuff", rows={
    ["Training_Blue_016"]={{{"FormatDescribe","TextMain"},"On entering combat: Movement Speed +50 for 30s (max stacks 1). Cooldown 60s."}},
    ["Training_Purple_016"]={{{"FormatDescribe","TextMain"},"When hit: moves back a short distance and gains Dodge +100 for 3s (max stacks 1). Cooldown 60s."}},
    ["Training_Purple_020"]={{{"FormatDescribe","TextMain"},"Attacks have a 20% chance to trigger: Max ATK +30, Movement Speed +80 for 5s (max stacks 1). Cooldown 30s."}},
    ["Training_Purple_010"]={{{"FormatDescribe","TextMain"},"Attacks have a 20% chance to rend the target, which loses 150 Torso HP over 30s."}},
    ["Training_Orange_014"]={{{"FormatDescribe","TextMain"},"Attacks have a 20% chance to rend the target: DEF -50 and Movement Speed -100, and it loses 100 Torso HP over 10s."}},
    ["Training_Orange_004"]={{{"FormatDescribe","TextMain"},"Fires a Hidden Weapon forward, dealing 300 Qi DMG. Cooldown 90s."}},
    ["Training_Orange_027"]={{{"FormatDescribe","TextMain"},"When hit, 10% chance to deal Blunt DMG equal to 10% of Attack to all enemies in range and knock them back. Cooldown 10s."}},
