  {path="/Game/Configs/Inventory/DT_InventoryItem.DT_InventoryItem", struct="FInventoryItem", name="DT_InventoryItem", rows={
    ["26001"]={{{"ItemDescription"},"When a disciple trains while carrying this item, it may be used up, and the disciple may gain one of its random effects.\nEach time it's used up: Balanced Martial Art EXP +100.\nChance of one bonus: Max Torso HP +50 permanently, up to 6 times (15%); Max Head HP +30 permanently, up to 6 times (15%).\nPut this item up for sale in the [Hundred Treasures Tower] and disciples will buy it themselves."},{{"FormatItemDescription","TextMain"},"When a disciple trains while carrying this item, it may be used up, and the disciple may gain one of its random effects.\nEach time it's used up: Balanced Martial Art EXP +100.\nChance of one bonus: Max Torso HP +50 permanently, up to 6 times (15%); Max Head HP +30 permanently, up to 6 times (15%).\nPut this item up for sale in the [Hundred Treasures Tower] and disciples will buy it themselves."}},
    ["26002"]={{{"ItemDescription"},"When a disciple trains while carrying this item, it may be used up, and the disciple may gain one of its random effects.\nEach time it's used up: Yang Martial Art EXP +100.\nChance of one bonus: Max HP of both arms +30 permanently, up to 6 times (15%); Max HP of both legs +30 permanently, up to 6 times (15%).\nPut this item up for sale in the [Hundred Treasures Tower] and disciples will buy it themselves."},{{"FormatItemDescription","TextMain"},"When a disciple trains while carrying this item, it may be used up, and the disciple may gain one of its random effects.\nEach time it's used up: Yang Martial Art EXP +100.\nChance of one bonus: Max HP of both arms +30 permanently, up to 6 times (15%); Max HP of both legs +30 permanently, up to 6 times (15%).\nPut this item up for sale in the [Hundred Treasures Tower] and disciples will buy it themselves."}},
    ["26003"]={{{"ItemDescription"},"When a disciple trains while carrying this item, it may be used up, and the disciple may gain one of its random effects.\nEach time it's used up: Sword Art EXP +100.\nChance of one bonus: Slashing Boost +1% permanently, up to 5 times (15%); Attack +1 permanently, up to 8 times (15%).\nPut this item up for sale in the [Hundred Treasures Tower] and disciples will buy it themselves."},{{"FormatItemDescription","TextMain"},"When a disciple trains while carrying this item, it may be used up, and the disciple may gain one of its random effects.\nEach time it's used up: Sword Art EXP +100.\nChance of one bonus: Slashing Boost +1% permanently, up to 5 times (15%); Attack +1 permanently, up to 8 times (15%).\nPut this item up for sale in the [Hundred Treasures Tower] and disciples will buy it themselves."}},
    ["26004"]={{{"ItemDescription"},"When a disciple trains while carrying this item, it may be used up, and the disciple may gain one of its random effects.\nEach time it's used up: Yin Martial Art EXP +100.\nChance of one bonus: Piercing Boost +1% permanently, up to 5 times (15%); Accuracy +1 permanently, up to 8 times (15%).\nPut this item up for sale in the [Hundred Treasures Tower] and disciples will buy it themselves."},{{"FormatItemDescription","TextMain"},"When a disciple trains while carrying this item, it may be used up, and the disciple may gain one of its random effects.\nEach time it's used up: Yin Martial Art EXP +100.\nChance of one bonus: Piercing Boost +1% permanently, up to 5 times (15%); Accuracy +1 permanently, up to 8 times (15%).\nPut this item up for sale in the [Hundred Treasures Tower] and disciples will buy it themselves."}},
    ["26005"]={{{"ItemDescription"},"When a disciple trains while carrying this item, it may be used up, and the disciple may gain one of its random effects.\nEach time it's used up: Lightness Skill EXP +100.\nChance of one bonus: Dodge +1 permanently, up to 5 times (15%); Movement and Running Speed +1 permanently, up to 5 times (15%).\nPut this item up for sale in the [Hundred Treasures Tower] and disciples will buy it themselves."},{{"FormatItemDescription","TextMain"},"When a disciple trains while carrying this item, it may be used up, and the disciple may gain one of its random effects.\nEach time it's used up: Lightness Skill EXP +100.\nChance of one bonus: Dodge +1 permanently, up to 5 times (15%); Movement and Running Speed +1 permanently, up to 5 times (15%).\nPut this item up for sale in the [Hundred Treasures Tower] and disciples will buy it themselves."}},
